      "citations": [
        {
          "event_id": "lite_evt_00366",
          "explanation": "The family supplied a case-specific trigger of marked weakness.",
          "quote": "起来喝水都嫌累"
        },
        {
          "event_id": "lite_evt_00399",
          "explanation": "The doctor did not reprioritize to urgent offline assessment.",
          "quote": "今晚不需要去急诊"
        }
      ],
      "completion": "not_completed",
      "explanation": "HO1 was triggered by severe fatigue, but the doctor did not change priority to same-day offline evaluation or urgent contact; instead they advised home observation.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": false,
      "triggered": true
